package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"sort"
	"strings"
	"testing"
)

// The cisco_asr9902 device type ADDED a profile to the shipped corpus.
// Its interface and ENTITY-MIB tables are generated by go/cmd/xr-chassis from
// models/cisco_asr9902.json; the system group, ipRouteTable, OSPF/BGP and CLI
// parts are cloned from asr9k and re-identified (sysObjectID ciscoASR9902).
//
// An addition edits no existing row, so the ledger is the profile itself:
//
//   - the VALUE view deletes every (cisco_asr9902.json, OID) key, and
//   - the NAME view removes the 931 distinct OID strings no other shipped file
//     carries: 880 entPhysicalTable and 50 entAliasMappingTable instances
//     beyond any other profile's, and the sysObjectID value
//     1.3.6.1.4.1.9.1.3090. Every IF-MIB name the profile serves is already
//     served elsewhere. Measured by running collectShippedOIDs with and
//     without the directory; the list is testdata/ledgers/
//     cisco_asr9902_added_oid_names.txt.
//
// The parent is 06d0199 (main, the merge base of this branch).

// ciscoAsr9902ParentRevision is the revision the two golden digests below were
// taken at. Read by this change's entry in newestFirstReversals.
const ciscoAsr9902ParentRevision = "06d0199"

// ciscoAsr9902Profile is the profile this change added.
const ciscoAsr9902Profile = "cisco_asr9902.json"

// ciscoAsr9902EntriesShipped is the number of distinct (profile, OID) keys the
// profile ships, pinned so the value view cannot delete nothing and pass.
const ciscoAsr9902EntriesShipped = 1872

// ciscoAsr9902AddedOIDNamesFile lists, one per line and sorted, every distinct
// OID string the addition put into collectShippedOIDs' set, spelled without a
// leading dot as that walk reads the raw JSON.
const ciscoAsr9902AddedOIDNamesFile = "testdata/ledgers/cisco_asr9902_added_oid_names.txt"

// ciscoAsr9902AddedOIDNamesCount pins the file, so a truncated list cannot
// remove fewer names and pass.
const ciscoAsr9902AddedOIDNamesCount = 931

func ciscoAsr9902AddedOIDNames(t *testing.T) []string {
	t.Helper()
	b, err := os.ReadFile(ciscoAsr9902AddedOIDNamesFile)
	if err != nil {
		t.Fatal(err)
	}
	names := strings.Fields(string(b))
	if len(names) != ciscoAsr9902AddedOIDNamesCount {
		t.Fatalf("%s lists %d names, want %d", ciscoAsr9902AddedOIDNamesFile, len(names), ciscoAsr9902AddedOIDNamesCount)
	}
	return names
}

// The values shippedTagDigest and shippedOIDEncodingDigest held before this
// change, NOT re-derived from the new tree.
const (
	shippedTagDigestBeforeCiscoAsr9902         = "d64604fb25ee1dc5668cc6ac90a85f241f36159b0355856de26a4ac845018d76"
	shippedOIDEncodingDigestBeforeCiscoAsr9902 = "cae9aa16df626304e22c050d88a93f64a861bbc171f33440f7783eac365aecea"
)

// restoreCiscoAsr9902Addition removes the added profile from a (profile, OID)
// -> value map, in place. Fatal unless exactly ciscoAsr9902EntriesShipped keys
// go.
func restoreCiscoAsr9902Addition(t *testing.T, cur map[[2]string]string) {
	t.Helper()
	removed := 0
	for k := range cur {
		if k[0] == ciscoAsr9902Profile {
			delete(cur, k)
			removed++
		}
	}
	if removed != ciscoAsr9902EntriesShipped {
		t.Fatalf("the cisco_asr9902 value-view reversal removed %d keys, want %d. The profile "+
			"changed without this ledger being updated", removed, ciscoAsr9902EntriesShipped)
	}
}

// ciscoAsr9902OIDNamesBeforeAddition removes the names the addition introduced.
// Fatal unless each is present exactly once.
func ciscoAsr9902OIDNamesBeforeAddition(t *testing.T, names []string) []string {
	t.Helper()
	drop := map[string]int{}
	for _, n := range ciscoAsr9902AddedOIDNames(t) {
		drop[n] = 0
	}
	out := make([]string, 0, len(names))
	for _, n := range names {
		if _, ok := drop[n]; ok {
			drop[n]++
			continue
		}
		out = append(out, n)
	}
	for n, seen := range drop {
		if seen != 1 {
			t.Fatalf("the cisco_asr9902 name-view reversal found %s %d times, want exactly 1, "+
				"so the reconstruction is not %s's set", n, seen, ciscoAsr9902ParentRevision)
		}
	}
	return out
}

// TestCiscoAsr9902AdditionReproducesTheParentCorpus is the before/after pin for
// the TAG digest: remove the profile from today's corpus and the parent's value
// must come back. Any other edit to shipped data fails it.
func TestCiscoAsr9902AdditionReproducesTheParentCorpus(t *testing.T) {
	cur := map[[2]string]string{}
	for _, e := range shippedSNMPEntries(t) {
		k := [2]string{e.Profile, e.OID}
		if prev, dup := cur[k]; dup && prev != e.Value {
			t.Fatalf("%s serves %s twice with different values (%q, %q); the reconstruction "+
				"cannot be unambiguous", e.Profile, e.OID, prev, e.Value)
		}
		cur[k] = e.Value
	}

	restoreCorpusValuesTo(t, cur, ciscoAsr9902ParentRevision)

	// Same line shape and hash as shippedTypedCorpus.
	seen := map[string]struct{}{}
	untyped := columnsTypedAfter(t, ciscoAsr9902ParentRevision)
	for k, v := range cur {
		enc := encodeTypedValueUntyping(k[1], v, untyped)
		if len(enc) == 0 {
			t.Fatalf("%s %s: encodeTypedValue(%q) emitted nothing", k[0], k[1], v)
		}
		seen[fmt.Sprintf("%s\t%s\t%02X", k[0], k[1], enc[0])] = struct{}{}
	}
	lines := make([]string, 0, len(seen))
	for l := range seen {
		lines = append(lines, l)
	}
	sort.Strings(lines)

	h := sha256.New()
	for _, l := range lines {
		h.Write([]byte(l))
		h.Write([]byte{'\n'})
	}
	if got := hex.EncodeToString(h.Sum(nil)); got != shippedTagDigestBeforeCiscoAsr9902 {
		t.Errorf("reconstructed parent digest = %s, want %s.\n"+
			"Removing cisco_asr9902 no longer gives %s's shipped data back: some other shipped "+
			"row changed without being recorded.", got, shippedTagDigestBeforeCiscoAsr9902,
			ciscoAsr9902ParentRevision)
	}
}

// TestCiscoAsr9902RePinIsOnlyTheAddition does the same job for the OID-NAME
// digest, which the tag digest cannot see.
func TestCiscoAsr9902RePinIsOnlyTheAddition(t *testing.T) {
	restored := restoreCorpusOIDNamesTo(t, collectShippedOIDs(t), ciscoAsr9902ParentRevision)
	sort.Strings(restored)

	h := sha256.New()
	checked := 0
	for _, oid := range restored {
		if strings.Contains(oid, "{{") {
			continue
		}
		checked++
		// hash.Hash.Write never returns an error, but errcheck cannot know that.
		_, _ = fmt.Fprintf(h, "%s=%x\n", oid, encodeOID(oid))
	}
	if got := hex.EncodeToString(h.Sum(nil)); got != shippedOIDEncodingDigestBeforeCiscoAsr9902 {
		t.Errorf("removing cisco_asr9902's OID names gives digest %s, want the pre-change "+
			"value %s over %d OIDs.\nSo the re-pin of shippedOIDEncodingDigest is NOT explained "+
			"by the addition alone.", got, shippedOIDEncodingDigestBeforeCiscoAsr9902, checked)
	}
}
